        private void SetupButton(Guna.UI2.WinForms.Guna2Button btn, string text, int tabIndex)
        {
            btn.ButtonMode = Guna.UI2.WinForms.Enums.ButtonMode.RadioButton;
            btn.BorderRadius = 8;
            btn.Dock = System.Windows.Forms.DockStyle.Top;
            btn.FillColor = System.Drawing.Color.Transparent;
            btn.Font = new System.Drawing.Font("Segoe UI", 10.5F, System.Drawing.FontStyle.Bold);
            btn.ForeColor = System.Drawing.Color.FromArgb(((int)(((byte)(158)))), ((int)(((byte)(161)))), ((int)(((byte)(176)))));
            btn.HoverState.FillColor = System.Drawing.Color.FromArgb(((int)(((byte)(46)))), ((int)(((byte)(51)))), ((int)(((byte)(73)))));
