            btn.CheckedState.ForeColor = System.Drawing.Color.FromArgb(((int)(((byte)(0)))), ((int)(((byte)(126)))), ((int)(((byte)(249)))));
            btn.Margin = new System.Windows.Forms.Padding(0, 0, 0, 8);
